<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DVD Logo Animation</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #000;
        }
        .dvd-logo {
            position: absolute;
            color: white;
            font-family: Arial, sans-serif;
            font-size: 48px;
            text-shadow: 2px 2px 4px rgba(255, 255, 255, 0.5);
        }
    </style>
</head>
<body>
    <div class="dvd-logo">DVD</div>

    <script>
        const dvd = document.querySelector('.dvd-logo');
        let x = 100;
        let y = 100;
        let dx = 2;
        let dy = 2;

        function update() {
            x += dx;
            y += dy;

            if (x <= 0 || x + dvd.offsetWidth >= window.innerWidth) {
                dx *= -1;
                // Bounce effect
                if (x <= 0) x = 0;
                else x = window.innerWidth - dvd.offsetWidth;
            }

            if (y <= 0 || y + dvd.offsetHeight >= window.innerHeight) {
                dy *= -1;
                // Bounce effect
                if (y <= 0) y = 0;
                else y = window.innerHeight - dvd.offsetHeight;
            }

            dvd.style.left = x + 'px';
            dvd.style.top = y + 'px';

            requestAnimationFrame(update);
        }

        update();
    </script>
</body>
</html>
